/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		propName: "restricted",
		value: api.data.get_current_project.result.restricted.value
	};
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    const data = { ...api.state.projectData,
        userId: [api.data.get_current_user_id.output.data.GlideDomain_Query.user.sys_id]
    };
    return {
        propName: "projectData",
        value: data,
    };
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		propName: 'isAvailableVersionPresent',
		value: api.data.check_available_project_version?.results.length>0?true:false
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	const { fields } = event.payload.data.output.data.snPo.GlidePromin.touchPointsStatus;
	return {
		propName: "touchPointsFields",
		value: fields
	};
}

